const GEMINI_API_KEY = "";
const TELEGRAM_TOKEN = "";

/**
 * Точка входа Webhook Telegram
 */
function doPost(e) {
  // Мгновенный ответ Telegram, что запрос принят
  const okOutput = ContentService.createTextOutput("OK").setMimeType(ContentService.MimeType.TEXT);

  try {
    if (!e || !e.postData || !e.postData.contents) return okOutput;

    const update = JSON.parse(e.postData.contents);
    if (!update.message || !update.message.text || update.message.from.is_bot) {
      return okOutput;
    }

    const updateId = update.update_id;
    const chatId = update.message.chat.id;
    const userText = update.message.text;

    // 1. ЗАЩИТА ОТ ДУБЛЕЙ: Проверяем, обрабатывали ли мы уже этот update_id
    const cache = CacheService.getScriptCache();
    if (cache.get("req_" + updateId)) {
      // Это повторный запрос от Telegram — просто игнорируем его
      return okOutput;
    }
    // Запоминаем update_id на 5 минут (300 секунд)
    cache.put("req_" + updateId, "true", 300);

    // Обработка /start
    if (userText === "/start") {
      sendTelegramMessage(chatId, "👋 Привет! Я твой AI-ассистент. Напиши, какой проект или задачу нужно создать.");
      return okOutput;
    }

    // Отправляем одно промежуточное сообщение
    sendTelegramMessage(chatId, "⏳ Запрос принят, обрабатываю...");

    // Выполняем логику Gemini прямо здесь
    const agentResult = runAgent(userText);

    // Формируем и отправляем ответ
    let responseText = "";
    if (typeof agentResult === 'object' && agentResult.status === 'success') {
      responseText = `✅ *Проект успешно создан!*\n\n` +
                     `📁 *Папка на Диске:* [Открыть](${agentResult.folderUrl})\n` +
                     `📌 *Задача в Google Tasks:* ${agentResult.folderName}`;
    } else {
      responseText = `🤖 *Ответ:* ${agentResult}`;
    }

    sendTelegramMessage(chatId, responseText);

  } catch (err) {
    Logger.log("Ошибка в doPost: " + err.toString());
  }

  return okOutput;
}

/**
 * Логика работы с Gemini API
 */
function runAgent(userPrompt) {
  // Используем актуальную модель gemini-3.8-flash
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent?key=${GEMINI_API_KEY}`;

  const tools = [{
    functionDeclarations: [
      {
        name: "createFolderAndTask",
        description: "Создает папку на Google Диске и задачу в Google Tasks со ссылкой на эту папку.",
        parameters: {
          type: "OBJECT",
          properties: {
            projectName: {
              type: "STRING",
              description: "Название проекта или задачи"
            }
          },
          required: ["projectName"]
        }
      }
    ]
  }];

  const payload = {
    contents: [{
      role: "user",
      parts: [{ text: userPrompt }]
    }],
    tools: tools
  };

  const options = {
    method: "post",
    contentType: "application/json",
    headers: {
      "Accept": "application/json"
    },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const responseCode = response.getResponseCode();
    const responseText = response.getContentText();

    // Превышение суточного/минутного лимита Free Tier
    if (responseCode === 429) {
      Logger.log("⚠️ Превышен лимит запросов Gemini API (429).");
      return "⚠️ Достигнут лимит бесплатных запросов Gemini (20 запр/день). Попробуйте позже или подлючите Billing в Google AI Studio.";
    }

    if (responseCode !== 200) {
      Logger.log(`❌ Ошибка API (${responseCode}): ${responseText}`);
      return `Ошибка Gemini API (${responseCode}): ${responseText}`;
    }

    const json = JSON.parse(responseText);

    if (!json.candidates || json.candidates.length === 0) {
      return "Gemini не вернула вариантов ответа.";
    }

    const part = json.candidates[0].content.parts[0];

    // 1. Обработка Function Calling
    if (part.functionCall && part.functionCall.name === "createFolderAndTask") {
      const projectName = part.functionCall.args.projectName;
      return executeCreateFolderAndTask(projectName);
    }

    // 2. Обычный текстовый ответ
    if (part.text) {
      return part.text;
    }

    return "Запрос обработан.";

  } catch (e) {
    Logger.log("❌ Исключение: " + e.toString());
    return "Ошибка выполнения: " + e.toString();
  }
}

/**
 * Исполнительная функция Google Apps Script
 */
function executeCreateFolderAndTask(projectName) {
  const folder = DriveApp.createFolder(projectName);
  const folderUrl = folder.getUrl();

  const task = Tasks.newTask();
  task.title = projectName;
  task.notes = `Папка проекта на Google Drive:\n${folderUrl}`;

  const createdTask = Tasks.Tasks.insert(task, '@default');

  return {
    status: "success",
    folderName: projectName,
    folderUrl: folderUrl,
    taskId: createdTask.id
  };
}

/**
 * Отправка сообщений в Telegram
 */
function sendTelegramMessage(chatId, text) {
  const url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage`;
  UrlFetchApp.fetch(url, {
    method: "post",
    contentType: "application/json",
    payload: JSON.stringify({
      chat_id: chatId,
      text: text,
      parse_mode: "Markdown",
      disable_web_page_preview: false
    })
  });
}

/**
 * СБРОС СТАРОЙ ОЧЕРЕДИ И ТРИГГЕРОВ (Запустить 1 раз вручную!)
 */
function hardReset() {
  // 1. Удаляем все активные триггеры
  const triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    ScriptApp.deleteTrigger(triggers[i]);
  }

  // 2. Сбрасываем очередь Telegram
  const WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzv1T_buK84F5IQOGW5gLWVsqR0cpo69RCOttPs7J__-lbe1udT-jQOeISsWoxbazeo/exec";
  const url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/setWebhook?url=${WEB_APP_URL}&drop_pending_updates=true`;
  const res = UrlFetchApp.fetch(url);
  Logger.log("Полная очистка завершена: " + res.getContentText());
}

function clearTelegramQueue() {
  // 1. Сбрасываем вебхук и принудительно стираем все застрявшие входящие сообщения
  const dropUrl = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/deleteWebhook?drop_pending_updates=true`;
  const res1 = UrlFetchApp.fetch(dropUrl);
  Logger.log("Очистка очереди Telegram: " + res1.getContentText());

  Utilities.sleep(2000); // пауза 2 секунды

  // 2. Подключаем вебхук заново
  const WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzv1T_buK84F5IQOGW5gLWVsqR0cpo69RCOttPs7J__-lbe1udT-jQOeISsWoxbazeo/exec";
const setUrl = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/setWebhook?url=${WEB_APP_URL}`;
  const res2 = UrlFetchApp.fetch(setUrl);
  Logger.log("Повторная установка Webhook: " + res2.getContentText());
}

function testRunner() {
  const result = runAgent("Создай проект Проверка Таймаута");
  Logger.log("Результат: " + JSON.stringify(result, null, 2));
}

function reloadWebhook() {
  const WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzv1T_buK84F5IQOGW5gLWVsqR0cpo69RCOttPs7J__-lbe1udT-jQOeISsWoxbazeo/exec";

  // Принудительно сбрасываем старый вебхук и очищаем зависшую очередь
  const deleteUrl = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/deleteWebhook?drop_pending_updates=true`;
  UrlFetchApp.fetch(deleteUrl);

  Utilities.sleep(1000); // пауза 1 сек

  // Устанавливаем вебхук заново
  const setUrl = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/setWebhook?url=${WEB_APP_URL}&drop_pending_updates=true`;
  const response = UrlFetchApp.fetch(setUrl);

  Logger.log("Результат обновления Webhook: " + response.getContentText());
}
